machine = re.compile(r'^(_\d+|[a-zA-Z]\d+|[a-zA-Z]|_?[a-zA-Z]{1,2}\d*)$')


def human(name):
    if name in keywords:
        return False
    if machine.match(name):
        return False
    return True


